style.css:
@-moz-document domain("maharashtraboardsolutions.in") {
/* CHANGE THIS SELECTOR IF NEEDED */
.custom-logo,
.site-logo img,
.logo img,
header img {

    position: relative !important;
    z-index: 5;

    animation: logoPulse 3s ease-in-out infinite !important;

    filter:
        drop-shadow(0 0 6px rgba(255,0,0,.8))
        drop-shadow(0 0 15px rgba(255,0,0,.6))
        drop-shadow(0 0 35px rgba(255,0,0,.45));
}

/* Background Aura */
.custom-logo::before,
.site-logo img::before,
.logo img::before,
header img::before{
    content:"";
    position:absolute;
    inset:-30px;
    z-index:-1;
    border-radius:50%;
    background:
        radial-gradient(circle,
        rgba(255,0,0,.35) 0%,
        rgba(255,0,0,.15) 40%,
        transparent 75%);
    animation: auraRotate 10s linear infinite;
    filter: blur(18px);
}

/* Pulsing */
@keyframes logoPulse{

0%{
transform:scale(1);
}

25%{
transform:scale(1.04);
}

50%{
transform:scale(1.08);
}

75%{
transform:scale(1.04);
}

100%{
transform:scale(1);
}

}

/* Rotating Aura */

@keyframes auraRotate{

0%{
transform:rotate(0deg) scale(1);
}

50%{
transform:rotate(180deg) scale(1.15);
}

100%{
transform:rotate(360deg) scale(1);
}

}
}
